import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import { parse as parseYaml } from "yaml";
import { checkAppConventions } from "../../scripts/check-app-conventions.mjs";
import { changedSteps, completeSteps } from "../../scripts/run-ci.mjs";

const cli = fileURLToPath(new URL("../../scripts/check-app-conventions.mjs", import.meta.url));
const repository = fileURLToPath(new URL("../../", import.meta.url));

const migration = `CREATE TABLE IF NOT EXISTS "user" (id TEXT PRIMARY KEY);
CREATE INDEX user_id_idx ON "user" (id);
`;
const schema = `-- Schema dump for @gdgjp/demo
-- Generated by scripts/dump-schema.sh from migrations/*.sql; do not edit by hand.

CREATE TABLE IF NOT EXISTS "user" (id TEXT PRIMARY KEY);
CREATE INDEX user_id_idx ON "user" (id);
`;

function manifest(name, extra = {}) {
  return JSON.stringify({
    name: `@gdgjp/${name}`,
    scripts: {
      "schema:dump": "bash ../../scripts/dump-schema.sh",
      "migrate:local": `wrangler d1 migrations apply gdgjp-${name}-db --local && pnpm schema:dump`,
      "migrate:remote": `wrangler d1 migrations apply gdgjp-${name}-db --remote && pnpm schema:dump`,
    },
    dependencies: { "@gdgjp/gdg-lib": "workspace:*" },
    ...extra,
  });
}

function fixture() {
  const root = mkdtempSync(join(tmpdir(), "app-conventions-"));
  const write = (path, text) => {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), text);
  };
  write("scripts/app-conventions.json", JSON.stringify({ llmFree: ["apps/demo"], baseline: [] }));
  write("apps/accounts/package.json", JSON.stringify({ name: "@gdgjp/accounts" }));
  write(
    "apps/accounts/wrangler.toml",
    '[vars]\nDEMO_CLIENT_ID = "demo"\nDEMO_REDIRECT_URLS = "https://demo.gdgs.jp/cb"\n',
  );
  write(
    "apps/accounts/.dev.vars.example",
    'DEMO_CLIENT_ID=demo\nDEMO_CLIENT_SECRET=""\nDEMO_REDIRECT_URLS=http://localhost:5200/cb\n',
  );
  write(
    "apps/accounts/vite.config.ts",
    "export default { server: { port: 5173, strictPort: true } };\n",
  );
  write(
    "apps/accounts/app/features/oauth/seed-clients.server.ts",
    "export const specs = (env) => [env.DEMO_CLIENT_ID];\n",
  );
  write("apps/demo/package.json", manifest("demo"));
  write(
    "apps/demo/wrangler.toml",
    '[vars]\nIDP_CLIENT_ID = "demo"\n\n[triggers]\ncrons = ["* * * * *", "0 * * * *"]\n',
  );
  write(
    "apps/demo/.dev.vars.example",
    'RP_SESSION_SECRET=""\nIDP_CLIENT_SECRET=""\nAPP_URL=http://localhost:5200\n',
  );
  write("apps/demo/vite.config.ts", "export default { server: {\n  port: 5200,\n} };\n");
  write("apps/demo/migrations/0001_init.sql", migration);
  write("apps/demo/schema.sql", schema);
  write(
    "apps/demo/workers/app.ts",
    'export const MINUTE_CRON = "* * * * *";\nexport const HOURLY_CRON = "0 * * * *";\n',
  );
  write("apps/demo/app/features/links/slug.ts", "export const slug = 1;\n");
  write("apps/demo/app/features/links/slug.routes.test.ts", "export {};\n");
  write("apps/demo/app/architecture.test.ts", "export {};\n");
  write("apps/demo/e2e/home.spec.ts", "export {};\n");
  write("packages/gdg-lib/package.json", JSON.stringify({ name: "@gdgjp/gdg-lib" }));
  write("packages/gdg-lib/src/cookie.ts", "export const encoder = new TextEncoder();\n");
  write("packages/gdg-lib/src/cookie.test.ts", 'import { test } from "node:test";\n');
  write("packages/gdg-lib/src/testing/durable-object.ts", 'import "node:sqlite";\n');
  write(
    "apps/demo/workers/app.test.ts",
    'import { fake } from "@gdgjp/gdg-lib/testing/durable-object";\n',
  );
  return {
    root,
    write,
    run: () => checkAppConventions(root),
    cleanup: () => rmSync(root, { recursive: true, force: true }),
  };
}

async function withFixture(action) {
  const f = fixture();
  try {
    await action(f);
  } finally {
    f.cleanup();
  }
}

async function errorsAfter(change) {
  let errors;
  await withFixture(async (f) => {
    change(f);
    errors = (await f.run()).errors;
  });
  return errors;
}

test("a conforming fixture passes", async () => {
  assert.deepEqual(await errorsAfter(() => {}), []);
});

test("schema.sql must equal the dump of migrations/", async () => {
  const errors = await errorsAfter((f) =>
    f.write("apps/demo/schema.sql", `${schema}CREATE TABLE extra (id TEXT);\n`),
  );
  assert.equal(errors.length, 1);
  assert.match(errors[0], /schema\.sql: differs from the schema that migrations\/ produce/);
  assert.match(errors[0], /new migration, run `pnpm --filter @gdgjp\/demo schema:dump`/);
});

test("the dump ignores the sqlite3 shell's IF NOT EXISTS and virtual-table annotations", async () => {
  const errors = await errorsAfter((f) => {
    f.write(
      "apps/demo/migrations/0002_search.sql",
      "CREATE VIRTUAL TABLE docs USING fts5(title);\n",
    );
    f.write(
      "apps/demo/schema.sql",
      [
        schema.replace('IF NOT EXISTS "user"', '"user"').trimEnd(),
        "CREATE VIRTUAL TABLE docs USING fts5(title)",
        "/* docs(title) */;",
        "CREATE TABLE IF NOT EXISTS 'docs_data'(id INTEGER PRIMARY KEY, block BLOB);",
        "CREATE TABLE IF NOT EXISTS 'docs_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;",
        "CREATE TABLE IF NOT EXISTS 'docs_content'(id INTEGER PRIMARY KEY, c0);",
        "CREATE TABLE IF NOT EXISTS 'docs_docsize'(id INTEGER PRIMARY KEY, sz BLOB);",
        "CREATE TABLE IF NOT EXISTS 'docs_config'(k PRIMARY KEY, v) WITHOUT ROWID;",
        "",
      ].join("\n"),
    );
  });
  assert.deepEqual(errors, []);
});

test("migrations need unique numbered names, apply cleanly, and regenerate schema.sql", async () => {
  const errors = await errorsAfter((f) => {
    f.write("apps/demo/migrations/0001_again.sql", "SELECT 1;\n");
    f.write("apps/demo/migrations/add-table.sql", "SELECT 1;\n");
    f.write(
      "apps/demo/package.json",
      manifest("demo", {
        scripts: { "migrate:local": "wrangler d1 migrations apply gdgjp-demo-db --local" },
      }),
    );
  });
  assert.ok(errors.some((error) => /0001_init\.sql: number 0001 is already used/.test(error)));
  assert.ok(errors.some((error) => /add-table\.sql: rename to NNNN_snake_case\.sql/.test(error)));
  assert.ok(errors.some((error) => /\[migration-scripts:apps\/demo\]/.test(error)));
  const broken = await errorsAfter((f) =>
    f.write("apps/demo/migrations/0002_broken.sql", "ALTER TABLE missing ADD COLUMN x TEXT;\n"),
  );
  assert.ok(broken.some((error) => /0002_broken\.sql: does not apply on SQLite/.test(error)));
});

test("a shared relying party declares its local secrets and is registered with Accounts", async () => {
  const errors = await errorsAfter((f) => {
    f.write("apps/demo/.dev.vars.example", "APP_URL=http://localhost:5200\n");
    f.write("apps/accounts/.dev.vars.example", "DEMO_CLIENT_ID=demo\n");
    f.write("apps/accounts/app/features/oauth/seed-clients.server.ts", "export {};\n");
  });
  assert.ok(errors.some((error) => /needs RP_SESSION_SECRET, IDP_CLIENT_SECRET/.test(error)));
  const registration = errors.find((error) => error.includes("[rp-registration:apps/demo]"));
  assert.match(registration, /DEMO_CLIENT_SECRET in apps\/accounts\/\.dev\.vars\.example/);
  assert.match(registration, /env\.DEMO_CLIENT_ID tuple in seed-clients\.server\.ts/);
  const unregistered = await errorsAfter((f) =>
    f.write("apps/accounts/wrangler.toml", '[vars]\nOTHER_CLIENT_ID = "other"\n'),
  );
  assert.ok(unregistered.some((error) => /is not registered with Accounts/.test(error)));
});

test("dev ports are unique and agree with APP_URL and the Accounts redirect", async () => {
  const errors = await errorsAfter((f) => {
    f.write(
      "apps/demo/vite.config.ts",
      "export default { server: { port: 5173, strictPort: true } };\n",
    );
  });
  assert.ok(errors.some((error) => /dev port 5173 is already used by apps\/accounts/.test(error)));
  assert.ok(
    errors.some((error) => /APP_URL uses port 5200, but the dev server listens/.test(error)),
  );
  assert.ok(errors.some((error) => /DEMO_REDIRECT_URLS points at port 5200/.test(error)));
});

test("an LLM-free app has no model binding, SDK, key or call", async () => {
  const errors = await errorsAfter((f) => {
    f.write(
      "apps/demo/wrangler.toml",
      '[vars]\nIDP_CLIENT_ID = "demo"\nGEMINI_MODEL = "x"\n\n[ai]\nbinding = "AI"\n',
    );
    f.write(
      "apps/demo/package.json",
      manifest("demo", { dependencies: { "@gdgjp/gdg-lib": "workspace:*", openai: "1" } }),
    );
    f.write("apps/demo/app/features/links/draft.server.ts", 'import OpenAI from "openai";\n');
    f.write("apps/demo/workers/app.ts", "export const run = (env) => env.AI.run('m');\n");
  });
  for (const reason of [
    /declares an AI binding/,
    /depends on openai/,
    /configures GEMINI_MODEL/,
    /draft\.server\.ts imports openai/,
    /app\.ts calls env\.AI\.run\(/,
  ]) {
    assert.ok(
      errors.some((error) => reason.test(error)),
      reason.source,
    );
  }
});

test("every scheduled cron is dispatched and every *_CRON constant is scheduled", async () => {
  const errors = await errorsAfter((f) =>
    f.write(
      "apps/demo/workers/app.ts",
      'export const MINUTE_CRON = "* * * * *";\nexport const NIGHTLY_CRON = "0 17 * * *";\n',
    ),
  );
  assert.ok(
    errors.some((error) => /schedules "0 \* \* \* \*", but no source names it/.test(error)),
  );
  assert.ok(errors.some((error) => /defines cron "0 17 \* \* \*", but wrangler\.toml/.test(error)));
});

test("unit tests sit beside their subject and Playwright specs stay in e2e/", async () => {
  const errors = await errorsAfter((f) => {
    f.write("apps/demo/app/features/links/orphan.test.ts", "export {};\n");
    f.write("apps/demo/app/routes/home.spec.ts", "export {};\n");
    f.write("packages/gdg-lib/src/lonely.test.ts", "export {};\n");
  });
  assert.ok(
    errors.some((error) =>
      error.includes("[test-colocation:apps/demo/app/features/links/orphan.test.ts]"),
    ),
  );
  assert.ok(
    errors.some((error) => error.includes("[spec-placement:apps/demo/app/routes/home.spec.ts]")),
  );
  assert.ok(
    errors.some((error) => error.includes("[test-colocation:packages/gdg-lib/src/lonely.test.ts]")),
  );
});

test("gdg-lib runtime code avoids node: and the test fake stays in tests", async () => {
  const errors = await errorsAfter((f) => {
    f.write("packages/gdg-lib/src/cookie.ts", 'import { createHmac } from "node:crypto";\n');
    f.write(
      "apps/demo/workers/app.ts",
      'export const MINUTE_CRON = "* * * * *";\nexport const HOURLY_CRON = "0 * * * *";\nimport { fake } from "@gdgjp/gdg-lib/testing/durable-object";\n',
    );
  });
  assert.ok(
    errors.some((error) =>
      /cookie\.ts: imports node:crypto, but @gdgjp\/gdg-lib runs inside Cloudflare Workers/.test(
        error,
      ),
    ),
  );
  assert.ok(errors.some((error) => /\[gdg-lib-testing:apps\/demo\/workers\/app\.ts\]/.test(error)));
});

test("app code reads bindings from the request context, not the cloudflare:workers env", async () => {
  const errors = await errorsAfter((f) =>
    f.write(
      "apps/demo/app/features/links/slug.ts",
      'import { DurableObject, env } from "cloudflare:workers";\nexport const slug = env;\n',
    ),
  );
  assert.equal(errors.length, 1);
  assert.match(
    errors[0],
    /slug\.ts: imports env from cloudflare:workers\. Read bindings from context/,
  );
});

test("the baseline suppresses known violations and must shrink when they are fixed", async () => {
  const id = "test-colocation:apps/demo/app/features/links/orphan.test.ts";
  const suppressed = await errorsAfter((f) => {
    f.write("apps/demo/app/features/links/orphan.test.ts", "export {};\n");
    f.write(
      "scripts/app-conventions.json",
      JSON.stringify({ llmFree: ["apps/demo"], baseline: [id] }),
    );
  });
  assert.deepEqual(suppressed, []);
  const stale = await errorsAfter((f) =>
    f.write(
      "scripts/app-conventions.json",
      JSON.stringify({ llmFree: ["apps/demo", "apps/gone"], baseline: [id] }),
    ),
  );
  assert.ok(
    stale.some((error) => /baseline entry ".*orphan\.test\.ts" no longer matches/.test(error)),
  );
  assert.ok(stale.some((error) => /llmFree lists apps\/gone/.test(error)));
});

test("the CLI exits non-zero with the fix in its message", async () => {
  await withFixture(async (f) => {
    const passing = spawnSync(process.execPath, [cli, "--root", f.root], { encoding: "utf8" });
    assert.equal(passing.status, 0, passing.stderr);
    f.write("apps/demo/app/features/links/orphan.test.ts", "export {};\n");
    const failing = spawnSync(process.execPath, [cli, "--root", f.root], { encoding: "utf8" });
    assert.equal(failing.status, 1);
    assert.match(failing.stderr, /name a sibling subject/);
  });
});

test("lint, local CI and the hosted policy job run the check", () => {
  const pkg = JSON.parse(readFileSync(join(repository, "package.json"), "utf8"));
  assert.match(pkg.scripts.lint, /node scripts\/check-app-conventions\.mjs/);
  assert.equal(pkg.scripts["check:apps"], "node scripts/check-app-conventions.mjs");
  for (const mode of ["quick", "full"]) {
    assert.ok(completeSteps(mode).some(([name]) => name === "app-conventions"));
    for (const file of [
      "apps/wiki/migrations/0099_new.sql",
      "packages/gdg-lib/src/index.ts",
      "scripts/app-conventions.json",
      "scripts/check-app-conventions.mjs",
    ]) {
      const step = changedSteps(mode, [file]).find(([name]) => name === "app-conventions");
      assert.equal(step?.[1], "node scripts/check-app-conventions.mjs", file);
    }
  }
  const workflow = parseYaml(readFileSync(join(repository, ".github/workflows/ci.yml"), "utf8"));
  const steps = workflow.jobs["code-comments"].steps;
  assert.ok(steps.some((step) => step.run === "node scripts/check-app-conventions.mjs"));
});
